const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'deals').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'microsoft.dynamics', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'dyn-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-12-dynamics-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'Dynamics 365 CRM is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to Dynamics 365 CRM - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'Dynamics 365 CRM is not connected yet - connect your account in Connections to get started.', 'connect');
const crmOrgUrl = String(cfg.crmOrgUrl || '').trim().replace(/\/+$/, '');
if (!crmOrgUrl) return refuse('org_misconfigured', 'Your organization has not configured its Dynamics 365 environment URL yet - ask your admin to set it in organization settings.', 'none');
let entity = 'opportunities';
let select = 'opportunityid,name,estimatedvalue,statecode,estimatedclosedate,description';
if (scope === 'accounts') { entity = 'accounts'; select = 'accountid,name,websiteurl,telephone1,address1_city,revenue'; }
if (scope === 'contacts') { entity = 'contacts'; select = 'contactid,fullname,emailaddress1,telephone1,jobtitle'; }
let url = '';
if (scope === 'deal') {
  if (!recordId) return refuse('empty', 'Provide an opportunity id to fetch a single Dynamics deal.', 'none');
  url = crmOrgUrl + '/api/data/v9.2/opportunities(' + encodeURIComponent(recordId) + ')?$select=' + select;
} else {
  url = crmOrgUrl + '/api/data/v9.2/' + entity + '?$top=' + limit + '&$select=' + select;
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url, entity: entity }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scope = (meta.diagnostics && meta.diagnostics.scope) || 'unknown';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'Dynamics 365 CRM returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'microsoft.dynamics', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('dyn-' + Date.now()), workflow: 'prism-12-dynamics-service' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
const raw = Array.isArray(res.value) ? res.value : [];
const records = raw.map(function (d) {
  if (scope === 'accounts') return { id: String(d.accountid || ''), name: d.name || '', website: d.websiteurl || '', phone: d.telephone1 || '', city: d.address1_city || '', revenue: d.revenue != null ? Number(d.revenue) : 0 };
  if (scope === 'contacts') return { id: String(d.contactid || ''), fullName: d.fullname || '', email: d.emailaddress1 || '', phone: d.telephone1 || '', title: d.jobtitle || '' };
  return { id: String(d.opportunityid || ''), name: d.name || '', amount: d.estimatedvalue != null ? Number(d.estimatedvalue) : 0, stage: d.statecode || '', closeDate: d.estimatedclosedate || '', description: d.description || '' };
});
finishSuccess(); envelope.records = records; envelope.total = records.length;
return [{ json: envelope }];
